import{_ as a,o as s,c as e,ag as i}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"SetLatchPos 设置PSO比较点","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/22. 飞拍指令/SetLatchPos.md","filePath":"3. 指令/22. 飞拍指令/SetLatchPos.md","lastUpdated":1778862643000}'),d={name:"3. 指令/22. 飞拍指令/SetLatchPos.md"};function h(n,t,r,l,o,p){return s(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="setlatchpos-设置pso比较点" tabindex="-1">SetLatchPos 设置PSO比较点 <a class="header-anchor" href="#setlatchpos-设置pso比较点" aria-label="Permalink to &quot;SetLatchPos 设置PSO比较点&quot;">​</a></h1><p>该指令用于设置机器人指定轴的指定 PSO 比较点，成功时返回机器人当前关节坐标。当机器人停在某一位置时执行该条指令，伺服会记录下当前指定轴的位置作为一个比较点，后续机器人运动到该位置时，伺服则会触发拍照信号。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetLatchPos(AxisID, ComparePointID, [RecordLatchID], Ret, P) SetLatchPos(轴号, 比较点编号, [过渡段记录点索引], 有效性, 关节位置)</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>AxisID</td><td>INTC</td><td>需要操作的机器人轴号。</td><td></td></tr><tr><td>ComparePointID</td><td>INTC</td><td>比较点的编号。</td><td></td></tr><tr><td>[RecordLatchID]</td><td>enum</td><td>过渡段记录点索引，对应 RecordLatchPos 指令所设置的 ID 号。取值：LATCH_1 ~ LATCH_20。</td><td>不使用过渡段记录点</td></tr><tr><td>Ret</td><td>INT</td><td>有效性返回值。</td><td></td></tr><tr><td>P</td><td>APOS</td><td>返回的机器人当前关节坐标。</td><td></td></tr></tbody></table><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetLatchPos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT0, P0)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析</strong>： 设置机器人 1 轴的第 1 个 PSO 比较点，伺服记录当前机器人 1 轴的位置，成功时返回机器人当前关节坐标。</p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetLatchPos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;LATCH_1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, INT0, P0)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>逻辑解析</strong>： 设置机器人 1 轴的第 1 个 PSO 比较点，使用 RecordLatchPos 所设置的过渡段上的比较点作为触发点，LATCH_1 对应 RecordLatchPos(1)。</p>',13)])])}const u=a(d,[["render",h]]);export{k as __pageData,u as default};
